Создайте новый файл `index.js` и добавьте в него следующий код:

```javascript
const { Client, GatewayIntentBits } = require('discord.js');
require('dotenv').config();

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'ban') {
    if (!interaction.memberPermissions?.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'Недостаточно прав для выполнения команды.', ephemeral: true });
    }

    const member = interaction.options.getMember('user');

    if (!member) {
      return interaction.reply({ content: 'Укажите пользователя для банирования.', ephemeral: true });
    }

    if (member.permissions.has('ADMINISTRATOR')) {
      return interaction.reply({ content: 'Невозможно банить администратора.', ephemeral: true });
    }

    await member.ban({ reason: `Команда /ban выполнена пользователем ${interaction.user.tag}` });

    interaction.reply({ content: `${member.user.tag} был забанен.` });
  }
});

client.login(process.env.TOKEN);
```

Сохраните файл и запустите бота с помощью команды:

```bash
node index.js
```

